import React from 'react';
import { Container, Row, Col, Card, Button } from 'react-bootstrap';
import { useCart } from '../context/CartProvider';
import { useNavigate } from 'react-router-dom';

const CheckoutPage = () => {
  const { items, total, clearCart } = useCart();
  const navigate = useNavigate();

  return (
    <Container className="py-5">
      <Row className="justify-content-center">
        <Col lg={8}>
          <Card className="border-0 shadow">
            <Card.Header className="bg-success text-white">
              <h2 className="mb-0">Checkout Complete!</h2>
            </Card.Header>
            <Card.Body className="text-center py-5">
              <i className="bi bi-check-circle-fill text-success" style={{ fontSize: '5rem' }}></i>
              <h2 className="mt-4">Thank You for Your Order</h2>
              <p className="lead">
                Your order of {items.length} tilapia products has been received.
              </p>
              
              <div className="mt-4 bg-light p-4 rounded">
                <h4>Order Summary</h4>
                <p className="mb-1">
                  <strong>Total Weight:</strong> {items.reduce((sum, item) => sum + item.quantity, 0).toFixed(2)} kg
                </p>
                <p className="mb-1">
                  <strong>Total Amount:</strong> ${total.toFixed(2)}
                </p>
                <p className="mb-0">
                  <strong>Order Number:</strong> #{Math.floor(Math.random() * 1000000)}
                </p>
              </div>
              
              <div className="mt-5">
                <p>
                  We'll send a confirmation email with delivery details. 
                  Our team is preparing your fresh tilapia order!
                </p>
                <Button 
                  variant="primary"
                  onClick={() => {
                    clearCart();
                    navigate('/');
                  }}
                  className="me-2"
                >
                  Continue Shopping
                </Button>
                <Button variant="outline-success">
                  View Order Details
                </Button>
              </div>
            </Card.Body>
          </Card>
        </Col>
      </Row>
    </Container>
  );
};

export default CheckoutPage;
